const wordTemplateBase64 = '';
const MAX_FILE_SIZE = 2 * 1024 * 1024 * 1024;
const PART_SIZE = 8 * 1024 * 1024;
const kinds = new Set(['video','audio','image','document','spreadsheet','attendance','signature','other']);
const json = (data, status = 200) => new Response(JSON.stringify(data), {status, headers:{'content-type':'application/json; charset=utf-8','cache-control':'no-store'}});
const error = (message, status = 400) => json({error:message},status);
const safeId = value => /^[a-f0-9-]{36}$/.test(value || '');
const meetingKey = id => 'meetings/index/' + id + '.json';
const metaKey = (id,fid) => 'meetings/files/' + id + '/' + fid + '.json';
const objectKey = (id,fid) => 'meetings/objects/' + id + '/' + fid;
