const wordClass = (task, base) => {if(task.status==='완료')return '완료';if(task.conflictValue&&task.changeApproval!=='공식승인됨')return '기한 충돌';if(!task.due||!base)return '기한 확인필요';const d=Date.parse(base+'T00:00:00Z')-Date.parse(task.due+'T00:00:00Z');return d>0?'기한 경과':d===0?'오늘 기한':'기한 미도래'};
