  let questions=[];for(const task of tasks){const c=wordClass(task,base),id=task.id||'업무번호 확인필요';if(c==='기한 경과')questions.push([id,'기한 경과','진행상태와 지연 사유를 확인해 주시기 바랍니다.']);if(c==='오늘 기한')questions.push([id,'오늘 기한','오늘 완료 가능 여부를 확인해 주시기 바랍니다.']);if(!task.assignee)questions.push([id,'담당','확정 담당자를 확인해 주시기 바랍니다.']);if(!task.due)questions.push([id,'기한','확정 기한을 확인해 주시기 바랍니다.']);if(!task.status||task.status==='상태 확인필요')questions.push([id,'진행상태','현재 진행상태를 확인해 주시기 바랍니다.']);if(c==='기한 충돌')questions.push([id,'변경 승인','기존 기한과 변경 후보 중 승인된 기한을 확인해 주시기 바랍니다.']);}
