  body+=wordP('7 검토','Heading1').replace('<w:pPr>','<w:pPr><w:pageBreakBefore/>');const audit=['전체 업무 = 완료 + 미완료','미완료 5대 기한 분류 합 = 미완료 전체','완료 업무의 미완료 기한 분류 제외','중복 발언 통합 및 원문번호 보존','단순 제안과 일정의 업무 수 제외','담당 기한 상태 임의 추정 금지','기한 변경과 충돌 후보값 보존','달력 날짜 차이 계산 정확','누락 충돌 확인 질문 반영','보고서와 집계의 건수 일치','이번 실행 범위 밖 자료 미합산'];body+=wordTable([['번호','무결성 검토 항목','결과'],...audit.map((x,i)=>[String(i+1),x,!valid?'산출 불가':i<3?'통과':'확인필요'])],true)+wordP('최종 사람 확인 필요 항목: '+(questions.length?questions.length+'건':'없음'));
