function stats(r){let s={all:r.tasks.length,done:0,open:0,overdue:0,today:0,future:0,unknown:0,conflict:0,ownerMissing:0,statusMissing:0};for(const t of r.tasks){const c=category(t,r.baseDate);if(c==='완료')s.done++;else{s.open++;if(c==='기한 경과')s.overdue++;else if(c==='오늘 기한')s.today++;else if(c==='기한 미도래')s.future++;else if(c==='기한 충돌')s.conflict++;else s.unknown++;}if(!t.assignee)s.ownerMissing++;if(!t.status||t.status==='상태 확인필요')s.statusMissing++;}return s}
