function frame(content){$('#app').innerHTML='<div class="shell">'+sidebar()+'<div class="main"><header class="topbar" id="topbar"></header><main class="content">'+content+'</main></div></div>'+(state.modal?modal():'')+(state.importDraft?importPanel():'');renderHeader()}
function render(){if(!state.record)renderHome();else{renderDetail();if(state.tab==='people')setupCanvas()}}
function renderHome(){const m=state.meetings,allTasks=m.reduce((a,x)=>a+(x.taskCount||0),0),attendees=m.reduce((a,x)=>a+(x.attendeeCount||0),0);frame('<div class="page-head"><div><div class="eyebrow">MEETING WORKSPACE</div><h1 class="page-title">회의 운영 현황</h1><div class="sub">회의 자료부터 후속 업무, 참석자 증빙까지 한곳에서 관리합니다.</div></div><div class="actions"><button class="btn primary" data-action="new">＋ 새 회의 등록</button></div></div><div class="hero"><div><div class="eyebrow" style="color:#b9cbff">SMART MEETING CONTROL</div><h2>회의가 끝난 뒤에도, 결정은 이어집니다.</h2><p>원문과 증빙을 남기고 담당·기한·진행상황을 검증해 주세요.</p></div><button class="btn" data-action="new">회의 시작하기 →</button></div><div class="cards"><div class="stat"><div class="label">전체 회의</div><div class="number">'+m.length+'</div><div class="hint">등록된 회의</div></div><div class="stat"><div class="label">후속 업무</div><div class="number">'+allTasks+'</div><div class="hint">관리 중인 업무</div></div><div class="stat"><div class="label">참석자</div><div class="number">'+attendees+'</div><div class="hint">등록된 참석 기록</div></div><div class="stat"><div class="label">저장 공간</div><div class="number" style="font-size:21px">연결됨</div><div class="hint">파일과 기록 보관</div></div></div><div class="panel"><div class="panel-header"><div class="panel-title">최근 회의</div><span class="muted" style="font-size:12px">'+m.length+'건</span></div>'+(m.length?'<div class="table-wrap"><table><thead><tr><th>회의명</th><th>회의일</th><th>자료 구분</th><th>후속 업무</th><th>최근 수정</th><th></th></tr></thead><tbody>'+m.map(x=>'<tr class="linkrow" data-action="open" data-id="'+x.id+'"><td class="strong">'+esc(x.title)+'</td><td>'+fmt(x.meetingDate)+'</td><td>'+badge(x.dataset||'일반')+'</td><td>'+x.taskCount+'건</td><td class="muted">'+esc((x.updatedAt||'').slice(0,10))+'</td><td>→</td></tr>').join('')+'</tbody></table></div>':'<div class="empty"><div class="empty-icon">▤</div><h3>아직 등록된 회의가 없습니다</h3><p>첫 회의를 만들고 동영상, 녹음, 사진, 워드 문서와 서명 자료를 추가해 주세요.</p><button class="btn primary" data-action="new">＋ 첫 회의 등록</button></div>')+'</div>')}
function modal(){return '<div class="modal-bg"><div class="modal"><div class="modal-head"><strong>새 회의 등록</strong><button class="btn small" data-action="close-modal">✕</button></div><div class="modal-body"><div class="field"><label>회의명 *</label><input id="new-title" placeholder="예: 보안 및 인프라 정기 주간회의" autofocus></div><div class="grid2"><div class="field"><label>회의일</label><input type="date" id="new-date" value="'+today()+'"></div><div class="field"><label>집계 기준일</label><input type="date" id="new-base" value="'+today()+'"></div><div class="field"><label>자료 구분</label><select id="new-dataset"><option>일반</option><option>자료 A</option><option>자료 B</option></select></div><div class="field"><label>자료 범위</label><select id="new-scope"><option>전체 자료</option><option>추가 자료</option><option>확인필요</option></select></div></div></div><div class="modal-foot"><button class="btn" data-action="close-modal">취소</button><button class="btn primary" data-action="create">회의 만들기</button></div></div></div>'}
function renderDetail(){const r=state.record,s=stats(r),tabs=[['overview','개요'],['minutes','회의록·진행상황'],['tasks','후속 업무'],['people','참석자·서명'],['files','파일 보관함'],['report','결과 보고서']];frame('<div class="page-head"><div><button class="btn small" data-action="home" style="margin-bottom:13px">← 전체 회의</button><div class="eyebrow">MEETING DETAIL</div><h1 class="page-title">'+esc(r.title)+'</h1><div class="sub">회의일 '+fmt(r.meetingDate)+' · 기준일 '+fmt(r.baseDate)+' · '+esc(r.dataset||'일반')+'</div></div><div class="actions"><button class="btn danger" data-action="delete-meeting">삭제</button><button class="btn primary" data-action="save" '+(state.busy?'disabled':'')+'>'+(state.dirty?'● 변경사항 저장':'✓ 저장됨')+'</button></div></div><div class="cards"><div class="stat"><div class="label">전체 후속 업무</div><div class="number">'+s.all+'</div><div class="hint">1업무 1건 기준</div></div><div class="stat"><div class="label">완료</div><div class="number">'+s.done+'</div><div class="hint">명시적으로 완료된 업무</div></div><div class="stat"><div class="label">미완료</div><div class="number">'+s.open+'</div><div class="hint">상태 확인필요 포함</div></div><div class="stat"><div class="label">기한 경과</div><div class="number accent">'+s.overdue+'</div><div class="hint">기준일 이전 기한</div></div></div><div class="tabs">'+tabs.map(([k,v])=>'<button data-action="tab" data-tab="'+k+'" class="'+(state.tab===k?'active':'')+'">'+v+'</button>').join('')+'</div><div id="tab-content">'+renderTab()+'</div>')}
function renderTab(){switch(state.tab){case 'overview':return overview();case 'minutes':return minutes();case 'tasks':return tasks();case 'people':return people();case 'files':return files();case 'report':return reportView();default:return ''}}
function field(label,key,type='text',hint=''){const v=state.record[key]||'';return '<div class="field"><label>'+label+'</label>'+(type==='textarea'?'<textarea data-field="'+key+'">'+esc(v)+'</textarea>':'<input type="'+type+'" data-field="'+key+'" value="'+esc(v)+'">')+(hint?'<small>'+hint+'</small>':'')+'</div>'}
function overview(){return '<div class="panel"><div class="panel-header"><div class="panel-title">회의 기본 정보</div><span class="badge">메타데이터</span></div><div class="panel-body"><div class="grid2">'+field('회의명','title')+field('회의일','meetingDate','date')+field('집계 기준일','baseDate','date')+field('회의 장소','location')+field('주관 부서·담당','organizer')+'<div class="field"><label>자료 구분</label><select data-field="dataset">'+['일반','자료 A','자료 B'].map(x=>'<option '+(state.record.dataset===x?'selected':'')+'>'+x+'</option>').join('')+'</select></div><div class="field"><label>자료 범위</label><select data-field="scope">'+['전체 자료','추가 자료','확인필요'].map(x=>'<option '+(state.record.scope===x?'selected':'')+'>'+x+'</option>').join('')+'</select></div>'+field('연결할 이전 결과 버전','previousVersion')+field('적용 버전','version')+'<div class="field full">'+field('운영 메모','notes','textarea')+'</div></div></div></div><div class="panel"><div class="panel-header"><div class="panel-title">입력 현황</div></div><div class="panel-body"><div class="grid3"><div><span class="muted">회의록 원문</span><h3>'+sourceCount(state.record.minutes,'M')+'개 기록</h3></div><div><span class="muted">진행상황 원문</span><h3>'+sourceCount(state.record.progress,'P')+'개 기록</h3></div><div><span class="muted">첨부 증빙</span><h3>'+state.files.length+'개 파일</h3></div></div><p class="section-note">원문이 비어 있거나 읽을 수 없는 경우 결과 보고서의 집계는 “산출 불가”로 표시합니다. 첨부 파일만 올린 경우 원문 내용을 확인하고 회의록·진행상황 칸에 옮겨 주세요.</p></div></div>'}
function sourceCount(text,prefix){return (text.match(new RegExp('\\['+prefix+'\\d+\\]','g'))||[]).length}
function minutes(){return '<div class="panel"><div class="panel-header"><div class="panel-title">회의록 및 진행상황 원문</div><button class="btn small" data-action="extract">결정 업무 후보 추출</button></div><div class="panel-body"><div class="section-note">발언 앞에 [M01], [M02]처럼 번호를 붙이고, 진행 기록 앞에 [P01], [P02]를 붙여 주세요. 아래에서 녹음·동영상·워드·엑셀 자료를 첨부하고 내용을 검토한 뒤 회의록 또는 진행상황에 반영할 수 있습니다. 음성 인식은 지원 브라우저에서만 실행되며 결과를 반드시 확인해 주세요.</div><div class="actions" style="margin:14px 0"><button class="btn primary small" data-action="tab" data-tab="files">＋ 녹음·동영상·문서 첨부 및 내용 반영</button></div><div class="grid2"><div class="field"><label>회의록 원문 (M번호)</label><textarea data-field="minutes" style="min-height:350px" placeholder="[M01] 박과장: 백업 서버 점검을 2026-10-27까지 수행하기로 결정함.">'+esc(state.record.minutes)+'</textarea></div><div class="field"><label>진행상황 및 변경 기록 (P번호)</label><textarea data-field="progress" style="min-height:350px" placeholder="[P01] (대상: M01) 진행상태: 완료 | 완료일: 2026-10-27 | 상세근거: ...">'+esc(state.record.progress)+'</textarea></div></div><div class="notice" style="margin-top:16px">업무 후보 추출은 명시적 결정 표현과 ISO 날짜만 읽습니다. 담당자·기한·상태가 불명확하면 추정하지 않고 확인필요로 남깁니다. 추출 결과를 검토한 뒤 저장해 주세요.</div></div></div>'}
function taskField(i,label,key,type='text',span=''){const t=state.record.tasks[i];const el=type==='select'?'<select data-task="'+i+'" data-key="'+key+'">'+['상태 확인필요','진행중','완료','보류'].map(x=>'<option '+(t[key]===x?'selected':'')+'>'+x+'</option>').join('')+'</select>':type==='approval'?'<select data-task="'+i+'" data-key="'+key+'">'+['해당없음','공식승인됨','미승인','승인 확인필요'].map(x=>'<option '+(t[key]===x?'selected':'')+'>'+x+'</option>').join('')+'</select>':type==='textarea'?'<textarea data-task="'+i+'" data-key="'+key+'">'+esc(t[key]||'')+'</textarea>':'<input type="'+type+'" data-task="'+i+'" data-key="'+key+'" value="'+esc(t[key]||'')+'">';return '<div class="field '+span+'"><label>'+label+'</label>'+el+'</div>'}
function tasks(){const r=state.record,s=stats(r);return '<div class="panel"><div class="panel-header"><div class="panel-title">후속 업무 관리</div><button class="btn primary small" data-action="add-task">＋ 업무 추가</button></div><div class="panel-body"><div class="section-note">완료는 진행상황에서 명시적으로 확인된 경우에만 선택해 주세요. 미승인 기한 변경은 기존 기한을 덮어쓰지 말고 충돌 후보값에 기록해 주세요.</div>'+(r.tasks.length?r.tasks.map((t,i)=>'<div class="task-card"><div class="task-head"><div><strong>'+esc(t.id)+'</strong> <span style="margin-left:8px">'+badge(category(t,r.baseDate))+'</span> <small class="muted" style="margin-left:8px">'+esc(reason(t,r.baseDate))+'</small></div><button class="btn small danger" data-action="remove-task" data-index="'+i+'">삭제</button></div><div class="task-fields">'+taskField(i,'업무번호','id')+taskField(i,'담당','assignee')+taskField(i,'진행상태','status','select')+taskField(i,'업무내용','text','textarea','full')+taskField(i,'확정기한','due','date')+taskField(i,'원문 기한 표현','rawDue')+taskField(i,'완료일','completedDate','date')+taskField(i,'기한 충돌 후보값','conflictValue')+taskField(i,'변경 승인 여부','changeApproval','approval')+taskField(i,'원문번호 (M/P)','sourceRefs')+taskField(i,'진행상황 근거','progressEvidence','textarea','span2')+'</div></div>').join(''):'<div class="empty" style="padding:35px"><div class="empty-icon">☷</div><h3>후속 업무가 없습니다</h3><p>회의록에서 결정 업무 후보를 추출하거나 직접 추가해 주세요.</p><button class="btn primary" data-action="add-task">＋ 업무 추가</button></div>')+'<div class="notice">집계 검증: 전체 '+s.all+'건 = 완료 '+s.done+'건 + 미완료 '+s.open+'건 / 미완료 '+s.open+'건 = 기한 경과 '+s.overdue+' + 오늘 '+s.today+' + 미도래 '+s.future+' + 확인필요 '+s.unknown+' + 충돌 '+s.conflict+'</div></div></div>'}
function people(){const r=state.record;return '<div class="split"><div><div class="panel"><div class="panel-header"><div class="panel-title">참석자 명부</div><button class="btn primary small" data-action="add-person">＋ 참석자 추가</button></div><div class="panel-body">'+(r.attendees.length?r.attendees.map((a,i)=>'<div class="task-card"><div class="task-fields" style="grid-template-columns:1fr 1fr auto"><div class="field"><label>이름</label><input data-person="'+i+'" data-key="name" value="'+esc(a.name)+'"></div><div class="field"><label>소속·직책</label><input data-person="'+i+'" data-key="role" value="'+esc(a.role)+'"></div><button class="btn small danger" data-action="remove-person" data-index="'+i+'">삭제</button><label><input type="checkbox" data-person="'+i+'" data-key="present" '+(a.present?'checked':'')+'> 참석</label><label><input type="checkbox" data-person="'+i+'" data-key="signed" '+(a.signed?'checked':'')+'> 서명 확인</label></div></div>').join(''):'<div class="empty" style="padding:30px"><p>참석자를 등록하고 서명 여부를 관리해 주세요.</p></div>')+'</div></div><div class="panel"><div class="panel-header"><div class="panel-title">서명 및 날인 증빙</div></div><div class="panel-body"><p class="sub">참석자 날인명부와 온라인 서명 파일은 파일 보관함에서 유형을 선택해 올릴 수 있습니다.</p><button class="btn" data-action="tab" data-tab="files">서명 파일 올리기 →</button></div></div></div><div><div class="panel"><div class="panel-header"><div class="panel-title">화면에서 직접 서명</div></div><div class="panel-body"><div class="field" style="margin-bottom:12px"><label>서명자</label><select id="signature-person"><option value="">이름을 선택하세요</option>'+r.attendees.map(a=>'<option value="'+esc(a.id)+'">'+esc(a.name||'이름 없음')+'</option>').join('')+'</select></div><div class="signature-wrap"><canvas id="signature-canvas"></canvas></div><div class="signature-controls"><button class="btn small" data-action="clear-signature">지우기</button><button class="btn primary small" data-action="save-signature">서명 저장</button></div><p class="sub" style="font-size:12px">서명은 PNG 증빙 파일로 저장됩니다. 법적 전자서명 인증은 별도 연동이 필요합니다.</p></div></div></div></div>'}
const kindName={video:'동영상',audio:'녹음·음성',image:'사진',document:'워드·문서',spreadsheet:'엑셀·표 자료',attendance:'참석자 날인명부',signature:'온라인 서명',other:'기타'};
function files(){return '<div class="split"><div class="panel"><div class="panel-header"><div class="panel-title">파일 업로드</div></div><div class="panel-body"><div class="field" style="margin-bottom:14px"><label>파일 유형</label><select id="file-kind">'+Object.entries(kindName).map(([k,v])=>'<option value="'+k+'">'+v+'</option>').join('')+'</select></div><label class="upload-zone" style="display:block;cursor:pointer"><strong>＋ 파일을 선택하거나 이 영역에 놓아 주세요</strong><p>녹음·동영상·Word(.docx)·Excel(.xlsx)·CSV·사진 등 · 파일당 최대 2GB</p><input type="file" id="file-input" multiple style="display:none" accept="video/*,audio/*,image/*,.doc,.docx,.pdf,.txt,.md,.csv,.xlsx,application/*"></label><div id="upload-progress" class="sub" style="margin-top:12px"></div><div class="notice" style="margin-top:15px">첨부 후 파일의 ‘내용 반영’을 누르세요. Word·Excel·텍스트는 내용을 추출해 검토하고, 녹음·동영상은 지원 브라우저에서 음성 인식을 시작할 수 있습니다. 영상 화면 자체와 사진·PDF의 내용은 자동 판독되지 않습니다.</div></div></div><div class="panel"><div class="panel-header"><div class="panel-title">보관된 파일</div><span class="muted" style="font-size:12px">'+state.files.length+'개</span></div><div class="panel-body">'+(state.files.length?'<div class="file-list">'+state.files.map(f=>'<div class="file"><div class="fileicon">'+(f.kind==='video'?'▶':f.kind==='audio'?'♪':f.kind==='image'?'▧':f.kind==='signature'?'✎':'▤')+'</div><div class="file-main"><strong>'+esc(f.name)+'</strong><small>'+esc(kindName[f.kind]||'기타')+' · '+size(f.size)+'</small></div><div class="file-actions"><a class="btn small" href="'+fileUrl(f)+'" target="_blank" rel="noopener">열기</a><button class="btn small" data-action="process-file" data-file="'+f.id+'">내용 반영</button><button class="btn small danger" data-action="delete-file" data-file="'+f.id+'">삭제</button></div></div>').join('')+'</div>':'<div class="empty" style="padding:38px"><div class="empty-icon">↥</div><h3>보관된 파일이 없습니다</h3><p>회의 영상과 녹음, 사진, 문서, 참석자 증빙을 올려 주세요.</p></div>')+'</div></div></div>'}
function importPanel(){const d=state.importDraft;if(!d)return '';const media=d.type==='audio'||d.type==='video';return '<div class="modal-bg" style="z-index:60"><div class="modal" style="width:min(880px,94vw);max-height:90vh;overflow:auto"><div class="modal-head"><strong>첨부 내용 확인 · '+esc(d.name)+'</strong><button class="btn small" data-action="dismiss-import">✕ 닫기</button></div><div class="modal-body"><p class="sub">자료 내용을 확인하고 필요한 부분만 회의록 또는 진행상황에 반영하세요. 원본 파일은 파일 보관함에 유지됩니다.</p>'+(media?'<div class="notice">브라우저가 음성 인식을 지원하면 재생되는 녹음·동영상의 음성을 글로 옮깁니다. 브라우저 음성 서비스가 음성을 외부에서 처리할 수 있습니다. 영상 화면은 분석하지 않습니다.</div><'+(d.type==='video'?'video':'audio')+' id="import-media" controls style="width:100%;max-height:260px;margin:12px 0" src="'+esc(d.url)+'"></'+(d.type==='video'?'video':'audio')+'><button class="btn small" data-action="start-transcription">▶ 음성 인식 시작</button>':'')+'<div id="import-status" class="sub" style="margin:10px 0">'+esc(d.status||'')+'</div><div class="field"><label>추출·녹취 내용 (검토 및 수정 가능)</label><textarea id="import-text" style="min-height:260px" placeholder="여기에 자료 내용을 확인하여 입력하거나 수정해 주세요.">'+esc(d.text||'')+'</textarea></div><div class="field" style="margin-top:12px"><label>반영 위치</label><select id="import-target"><option value="minutes" '+(d.target==='minutes'?'selected':'')+'>회의록 원문 (M번호)</option><option value="progress" '+(d.target==='progress'?'selected':'')+'>진행상황 및 참고자료 (P번호)</option></select></div></div><div class="modal-foot"><button class="btn" data-action="dismiss-import">취소</button><button class="btn primary" data-action="apply-import">검토한 내용 반영·저장</button></div></div></div>'}
const xmlItems=(node,tag)=>Array.from(node.getElementsByTagNameNS('*',tag));
async function readDocx(blob){if(!window.JSZip)throw Error('문서 읽기 도구를 불러오지 못했습니다. 새로고침해 주세요.');const zip=await JSZip.loadAsync(blob),entry=zip.file('word/document.xml');if(!entry)throw Error('Word 문서 본문을 찾을 수 없습니다.');const doc=new DOMParser().parseFromString(await entry.async('string'),'application/xml');if(doc.querySelector('parsererror'))throw Error('Word 문서를 읽을 수 없습니다.');return xmlItems(doc,'p').map(p=>xmlItems(p,'t').map(t=>t.textContent).join('').trim()).filter(Boolean).join('\n').slice(0,220000)}
async function readXlsx(blob){if(!window.JSZip)throw Error('엑셀 읽기 도구를 불러오지 못했습니다. 새로고침해 주세요.');const zip=await JSZip.loadAsync(blob),shared=zip.file('xl/sharedStrings.xml'),strings=shared?xmlItems(new DOMParser().parseFromString(await shared.async('string'),'application/xml'),'si').map(si=>xmlItems(si,'t').map(t=>t.textContent).join('')):[];let output=[];const sheets=Object.keys(zip.files).filter(x=>/^xl\/worksheets\/sheet\d+\.xml$/.test(x)).sort((a,b)=>Number(a.match(/sheet(\d+)/)[1])-Number(b.match(/sheet(\d+)/)[1])).slice(0,10);if(!sheets.length)throw Error('엑셀 시트를 찾을 수 없습니다.');for(const path of sheets){const doc=new DOMParser().parseFromString(await zip.file(path).async('string'),'application/xml');output.push('['+path.split('/').pop().replace('.xml','')+']');for(const row of xmlItems(doc,'row').slice(0,300)){const cells=xmlItems(row,'c').map(c=>{const ref=c.getAttribute('r')||'',kind=c.getAttribute('t'),v=xmlItems(c,'v')[0]?.textContent||'',value=kind==='s'?strings[Number(v)]||'':kind==='inlineStr'?xmlItems(c,'t').map(t=>t.textContent).join(''):v;return value?ref+': '+value:''}).filter(Boolean);if(cells.length)output.push(cells.join(' | '));}if(output.join('\n').length>220000)break;}return output.join('\n').slice(0,220000)}
async function processAttachment(fid){const f=state.files.find(x=>x.id===fid);if(!f)return;const ext=(f.name.split('.').pop()||'').toLowerCase(),type=/^audio\//.test(f.type)||f.kind==='audio'?'audio':/^video\//.test(f.type)||f.kind==='video'?'video':'document';const target=type==='audio'||type==='video'||ext==='docx'?'minutes':'progress';state.importDraft={fileId:f.id,name:f.name,type,target,text:'',status:'내용을 읽는 중입니다.',url:fileUrl(f)};render();try{let text='';if(ext==='docx'||ext==='xlsx'){if(f.size>40*1024*1024)throw Error('문서 자동 읽기는 40MB 이하 파일에서 사용할 수 있습니다.');const response=await fetch(fileUrl(f));if(!response.ok)throw Error('첨부 파일을 불러오지 못했습니다.');const blob=await response.blob();text=ext==='docx'?await readDocx(blob):await readXlsx(blob);}else if(['txt','md','csv','tsv'].includes(ext)){const response=await fetch(fileUrl(f));if(!response.ok)throw Error('첨부 파일을 불러오지 못했습니다.');text=(await response.text()).slice(0,220000)}else if(type==='audio'||type==='video'){state.importDraft.status='재생 버튼 또는 음성 인식 시작을 누르세요. 인식 결과를 검토 후 반영할 수 있습니다.';render();return}else throw Error('이 형식은 자동 본문 읽기를 지원하지 않습니다. .docx, .xlsx, .txt, .csv 파일을 사용하거나 내용을 직접 입력해 주세요.');state.importDraft.text=text;state.importDraft.status=text?'내용을 추출했습니다. 정확성을 확인해 주세요.':'읽을 수 있는 내용이 없습니다. 직접 입력해 주세요.';render()}catch(e){state.importDraft.status=e.message;render()}}
async function startTranscription(){const d=state.importDraft,media=$('#import-media'),Speech=window.SpeechRecognition||window.webkitSpeechRecognition;if(!d||!media)return;if(state.speech){notify('음성 인식이 진행 중입니다.');return}if(!Speech){$('#import-status').textContent='이 브라우저는 음성 인식을 지원하지 않습니다. 파일을 재생하며 녹취문을 직접 입력해 주세요.';return}if(typeof media.captureStream!=='function'&&typeof media.webkitCaptureStream!=='function'){$('#import-status').textContent='이 브라우저는 파일 음성 추출을 지원하지 않습니다. Chrome 또는 Edge에서 다시 시도하거나 녹취문을 직접 입력해 주세요.';return}try{await media.play();const stream=(media.captureStream||media.webkitCaptureStream).call(media),track=stream.getAudioTracks()[0];if(!track)throw Error('파일에서 음성 트랙을 찾을 수 없습니다.');const recognition=new Speech();recognition.lang='ko-KR';recognition.continuous=true;recognition.interimResults=true;const before=($('#import-text')?.value||'').trim();recognition.onresult=e=>{let parts=[];for(let i=0;i<e.results.length;i++)parts.push(e.results[i][0]?.transcript||'');const text=parts.join(' ').trim();if(text){d.text=[before,text].filter(Boolean).join(' ');const box=$('#import-text');if(box)box.value=d.text}};recognition.onerror=e=>{$('#import-status').textContent='음성 인식 오류: '+(e.error||'알 수 없음')+'. 녹취문을 직접 수정할 수 있습니다.'};recognition.onend=()=>{state.speech=null;if($('#import-status'))$('#import-status').textContent='음성 인식이 종료되었습니다. 재생 중이었다면 다시 시작해 이어서 인식할 수 있습니다. 결과를 확인해 주세요.'};media.onended=()=>recognition.stop();recognition.start(track);state.speech=recognition;$('#import-status').textContent='재생하며 음성을 인식 중입니다. 파일 길이만큼 시간이 걸립니다.'}catch(e){media.pause();$('#import-status').textContent='음성 인식을 시작하지 못했습니다: '+e.message+'. 녹취문을 직접 입력해 주세요.'}}
function closeImport(){try{state.speech?.stop()}catch{}state.speech=null;const media=$('#import-media');if(media)media.pause();state.importDraft=null;render()}
async function applyImport(){const d=state.importDraft;if(!d)return;const text=($('#import-text')?.value||'').trim(),target=$('#import-target')?.value==='progress'?'progress':'minutes';if(!text){notify('반영할 내용을 입력해 주세요.');return}if((state.record.importedSources||[]).some(x=>x.fileId===d.fileId&&x.target===target)&&!confirm('이 파일을 같은 위치에 다시 반영할까요?'))return;const prefix=target==='progress'?'P':'M',current=state.record[target]||'',nums=Array.from(current.matchAll(new RegExp('\\['+prefix+'(\\d+)\\]','g'))).map(x=>Number(x[1])),start=Math.max(0,...nums)+1;const lines=text.replace(/\r/g,'').split('\n').map(x=>x.trim()).filter(Boolean).slice(0,500);const added=lines.map((line,i)=>'['+prefix+String(start+i).padStart(2,'0')+'] (첨부: '+d.name+') '+line.replace(/^\[[MP]\d+\]\s*/,''));if((current+'\n'+added.join('\n')).length>300000){notify('원문 입력 한도를 초과합니다. 필요한 부분만 선택해 주세요.');return}state.record[target]=(current?current+'\n':'')+added.join('\n');state.record.importedSources=state.record.importedSources||[];state.record.importedSources.push({fileId:d.fileId,name:d.name,target,at:new Date().toISOString()});state.dirty=true;closeImport();state.tab='minutes';await save()}

async function uploadFile(file,kind){if(file.size>2147483648)throw Error('2GB를 초과한 파일은 업로드할 수 없습니다.');const id=state.record.id;let start=await api('/meetings/'+id+'/upload/start',{method:'POST',body:JSON.stringify({name:file.name,type:file.type||'application/octet-stream',size:file.size,kind})});let parts=[],total=Math.ceil(file.size/start.partSize);for(let i=0;i<total;i++){const blob=file.slice(i*start.partSize,Math.min(file.size,(i+1)*start.partSize));const part=await api('/meetings/'+id+'/upload/part?fileId='+start.fileId+'&uploadId='+encodeURIComponent(start.uploadId)+'&partNumber='+(i+1),{method:'PUT',body:blob});parts.push(part);const p=$('#upload-progress');if(p)p.textContent=file.name+' · '+Math.round((i+1)/total*100)+'% 업로드 중';}await api('/meetings/'+id+'/upload/complete',{method:'POST',body:JSON.stringify({fileId:start.fileId,uploadId:start.uploadId,parts})});state.files=await api('/meetings/'+id+'/files');render();notify(file.name+' 파일을 저장했습니다.');}
async function uploadSelected(input){const selectedKind=$('#file-kind')?.value||'other';for(const file of input.files){const kind=/\.xlsx?$/i.test(file.name)?'spreadsheet':/\.docx?$/i.test(file.name)?'document':/^audio\//.test(file.type)?'audio':/^video\//.test(file.type)?'video':selectedKind;try{await uploadFile(file,kind)}catch(e){notify(e.message)}}}
async function deleteFile(fid){if(!confirm('이 파일을 삭제할까요?'))return;try{await api('/meetings/'+state.record.id+'/files/'+fid,{method:'DELETE'});state.files=await api('/meetings/'+state.record.id+'/files');render();notify('파일을 삭제했습니다.')}catch(e){notify(e.message)}}
function extract(){const lines=state.record.minutes.split(/\r?\n/),existing=new Set(state.record.tasks.flatMap(t=>(t.sourceRefs||'').match(/M\d+/g)||[]));let count=0;for(const line of lines){const m=line.match(/^\s*\[(M\d+)\]\s*(.+)$/);if(!m||existing.has(m[1]))continue;const raw=m[2];if(/제안|아이디어|추후 검토|다음.*회의|회의.*일정/.test(raw))continue;if(!/하기로 결정|진행하기로|수행하기로|완료하기로|마쳐주시기 바랍니다|작성하기로|적용하기로/.test(raw))continue;const due=(raw.match(/20\d{2}-\d{2}-\d{2}/)||[])[0]||'',rawDue=(raw.match(/\d{1,2}월\s*\d{1,2}일|빠른 시일 내|미정/)||[])[0]||due;state.record.tasks.push({id:'T'+String(state.record.tasks.length+1).padStart(2,'0'),text:raw,assignee:'',due,rawDue,status:'상태 확인필요',completedDate:'',sourceRefs:m[1],progressEvidence:'',conflictValue:'',changeApproval:'해당없음'});existing.add(m[1]);count++;}state.dirty=true;state.tab='tasks';render();notify(count?count+'개 결정 업무 후보를 추가했습니다. 검토 후 저장해 주세요.':'새로 추출할 명시적 결정 문장이 없습니다.');}
const md=v=>String(v??'').replaceAll('|','\\|').replace(/\r?\n/g,' / ')||'확인필요';
function numbered(text,prefix){return text.split(/\r?\n/).map(line=>{const m=line.match(new RegExp('^\\s*\\[('+prefix+'\\d+)\\]\\s*(.*)$'));return m?{id:m[1],text:m[2]}:null}).filter(Boolean)}
function markdown(){const r=state.record,s=stats(r),ms=numbered(r.minutes,'M'),ps=numbered(r.progress,'P'),valid=!!r.minutes.trim(),sumOK=s.all===s.done+s.open&&s.open===s.overdue+s.today+s.future+s.unknown+s.conflict,calc=valid?String(s.all):'산출 불가';let lines=[];const add=(...x)=>lines.push(...x);add('# '+r.title,'','## 1. 실행 정보 및 자료 확인','', '| 항목 | 내용 |','| --- | --- |','| 자료 구분 | '+md(r.dataset)+' |','| 기준일 | '+md(r.baseDate)+' |','| 회의명 / 회의일 | '+md(r.title)+' / '+md(r.meetingDate)+' |','| 자료 범위 | '+md(r.scope)+' |','| 연결 이전 버전 | '+md(r.previousVersion)+' |','| 적용 버전 | '+md(r.version)+' |','| 회의록 확인 | '+(valid?'포함 · '+ms.length+'개 M 기록':'원문 없음 · 집계 산출 불가')+' |','| 진행상황 확인 | '+(r.progress.trim()?'포함 · '+ps.length+'개 P 기록':'원문 없음')+' |','| 첨부 파일 | '+state.files.length+'개 |','| 원문 기록 수 vs 통합 업무 수 | '+ms.length+'개 M 기록, '+ps.length+'개 P 기록 → '+calc+'개 업무 |','');
add('## 2. 후속 업무 목록','','### 2-1. 미완료 업무','','| 업무번호 | 업무내용 | 담당 | 확정기한 | 원문기한표현 | 진행상태 | 기한분류 | 경과일수 | 확인항목 | 원문번호 | 진행상황근거 |','| --- | --- | --- | --- | --- | --- | --- | --- | --- | --- | --- |');for(const t of r.tasks.filter(x=>x.status!=='완료').sort((a,b)=>['기한 경과','오늘 기한','기한 미도래','기한 확인필요','기한 충돌'].indexOf(category(a,r.baseDate))-['기한 경과','오늘 기한','기한 미도래','기한 확인필요','기한 충돌'].indexOf(category(b,r.baseDate)))){const checks=[!t.assignee?'담당 확인필요':'',!t.due?'기한 확인필요':'',!t.status||t.status==='상태 확인필요'?'상태 확인필요':'',category(t,r.baseDate)==='기한 충돌'?'기한 충돌':''].filter(Boolean).join(', ')||'없음';add('| '+[t.id,t.text,t.assignee||'확인필요',category(t,r.baseDate)==='기한 충돌'?(t.due||'확인필요')+' vs '+t.conflictValue:(t.due||'확인필요'),t.rawDue||'확인필요',t.status||'상태 확인필요',category(t,r.baseDate),reason(t,r.baseDate),checks,t.sourceRefs||'확인필요',t.progressEvidence||'기록 없음'].map(md).join(' | ')+' |');}if(!r.tasks.some(x=>x.status!=='완료'))add('| 해당없음 | | | | | | | | | | |');add('','### 2-2. 완료 업무','','| 업무번호 | 업무내용 | 담당 | 확정기한 | 완료일 | 원문번호 | 완료 근거 |','| --- | --- | --- | --- | --- | --- | --- |');for(const t of r.tasks.filter(x=>x.status==='완료'))add('| '+[t.id,t.text,t.assignee||'확인필요',t.due||'확인필요',t.completedDate||'확인필요',t.sourceRefs||'확인필요',t.progressEvidence||'근거 확인필요'].map(md).join(' | ')+' |');if(!s.done)add('| 해당없음 | | | | | | |');add('','### 2-3. 변경 및 충돌 기록','','| 업무번호 | 이전값 / 충돌 후보 | 변경 승인 | 반영 여부 | 원문 근거 |','| --- | --- | --- | --- | --- |');const changed=r.tasks.filter(t=>t.conflictValue);for(const t of changed)add('| '+[t.id,(t.due||'확인필요')+' vs '+t.conflictValue,t.changeApproval||'확인필요',t.changeApproval==='공식승인됨'?'승인 기록 확인 필요':'보류(미승인)',t.sourceRefs||'확인필요'].map(md).join(' | ')+' |');if(!changed.length)add('| 해당없음 | | | | |');
add('','## 3. 집계','','| 구분 | 건수 | 근거 |','| --- | ---: | --- |','| 전체 업무 | '+calc+' | 완료 + 미완료 |','| 완료 | '+(valid?s.done:'산출 불가')+' | 명시적으로 완료된 업무 |','| 미완료 | '+(valid?s.open:'산출 불가')+' | 아래 5개 분류의 합계 |','| 기한 경과 | '+(valid?s.overdue:'산출 불가')+' | 확정기한 < 기준일 |','| 오늘 기한 | '+(valid?s.today:'산출 불가')+' | 확정기한 = 기준일 |','| 기한 미도래 | '+(valid?s.future:'산출 불가')+' | 확정기한 > 기준일 |','| 기한 확인필요 | '+(valid?s.unknown:'산출 불가')+' | 날짜 누락 또는 모호함 |','| 기한 충돌 | '+(valid?s.conflict:'산출 불가')+' | 미승인 복수 기한 |','| 담당 확인필요 (별도 지표) | '+(valid?s.ownerMissing:'산출 불가')+' | 전체 업무에 중복 합산하지 않음 |','| 상태 확인필요 (별도 지표) | '+(valid?s.statusMissing:'산출 불가')+' | 미완료에 포함 |','',valid?'**교차 검증:** 전체 '+s.all+' = 완료 '+s.done+' + 미완료 '+s.open+' / 미완료 '+s.open+' = '+[s.overdue,s.today,s.future,s.unknown,s.conflict].join(' + ')+' · '+(sumOK?'일치합니다.':'[검토필요] 불일치합니다.'):'**교차 검증:** 회의록 원문이 없어 산출 불가입니다.','');
add('## 4. 참고사항 (업무 제외 항목)','','| 구분 | 원문번호 | 내용 | 제외 사유 |','| --- | --- | --- | --- |');let refs=ms.filter(x=>/제안|아이디어|추후 검토|다음.*회의|회의.*일정/.test(x.text));for(const x of refs)add('| '+[/다음.*회의|회의.*일정/.test(x.text)?'다음 회의 일정':'단순 제안',x.id,x.text,'실행 업무로 확정되지 않음'].map(md).join(' | ')+' |');if(!refs.length)add('| 없음 | | | |');
add('','## 5. 확인 질문','','| 업무번호 | 확인 대상 | 질문 | 원문 근거 |','| --- | --- | --- | --- |');let qs=[];if(r.scope==='확인필요'||!r.scope)qs.push(['실행 정보','자료 범위','이번 입력은 전체 자료입니까, 추가 자료입니까?','실행 메타데이터']);for(const t of r.tasks){const c=category(t,r.baseDate),ref=t.sourceRefs||'원문번호 확인필요';if(c==='기한 경과')qs.push([t.id,'지연 및 상태','기한이 '+reason(t,r.baseDate)+'했습니다. 진행상태와 지연 사유를 확인해 주시기 바랍니다.',ref]);if(c==='오늘 기한')qs.push([t.id,'오늘 기한','오늘 완료 가능 여부를 확인해 주시기 바랍니다.',ref]);if(!t.assignee)qs.push([t.id,'담당','확정 담당자를 확인해 주시기 바랍니다.',ref]);if(!t.due)qs.push([t.id,'기한','확정 기한을 YYYY-MM-DD로 확인해 주시기 바랍니다.',ref]);if(!t.status||t.status==='상태 확인필요')qs.push([t.id,'진행상태','현재 진행상태를 확인해 주시기 바랍니다.',ref]);if(c==='기한 충돌')qs.push([t.id,'변경 승인','기존 기한 '+(t.due||'확인필요')+'과 변경 후보 '+t.conflictValue+' 중 승인된 기한을 확인해 주시기 바랍니다.',ref]);if(t.status==='완료'&&!t.completedDate)qs.push([t.id,'완료일','완료일과 근거를 확인해 주시기 바랍니다.',ref]);}for(const q of qs)add('| '+q.map(md).join(' | ')+' |');if(!qs.length)add('| 없음 | | | |');
add('','## 6. 주간 보고서','','- **보고 개요:** '+md(r.dataset)+' / 기준일 '+md(r.baseDate)+' / 범위 '+md(r.scope)+' / 전체 업무 '+calc+'건입니다.','- **완료 업무:** '+(valid?s.done+'건이 명시적으로 완료되었습니다.':'원문이 없어 산출 불가입니다.'),'- **미완료 업무:** '+(valid?s.open+'건이며 기한 경과 '+s.overdue+'건, 오늘 기한 '+s.today+'건입니다.':'원문이 없어 산출 불가입니다.'),'- **확인 요청:** 담당 누락 '+(valid?s.ownerMissing:'산출 불가')+'건, 상태 확인필요 '+(valid?s.statusMissing:'산출 불가')+'건, 기한 충돌 '+(valid?s.conflict:'산출 불가')+'건입니다.','- **차기 일정:** '+(refs.find(x=>/다음.*회의|회의.*일정/.test(x.text))?.text||'확인필요')+'','## 7. 검토 (11대 무결성 감사 체크리스트)','','| 번호 | 검토 항목 | 결과 |','| ---: | --- | --- |');const audit=[['회의록 원문 존재',valid],['M 원문번호 확인',ms.length>0],['자료 범위 확인',!!r.scope&&r.scope!=='확인필요'],['업무 원문번호 보존',r.tasks.every(t=>!!t.sourceRefs)],['11개 업무 필드 구조',true],['담당·기한 추정 방지',true],['변경·충돌 후보값 보존',r.tasks.every(t=>!t.conflictValue||!!t.changeApproval)],['완료 근거 확인',r.tasks.filter(t=>t.status==='완료').every(t=>!!t.progressEvidence)],['미완료 5대 분류',sumOK],['집계 교차 검증',valid&&sumOK],['보고서 수치 정합성',valid&&sumOK]];audit.forEach((a,i)=>add('| '+(i+1)+' | '+a[0]+' | '+(a[1]?'통과':'확인필요')+' |'));add('','**최종 사람 확인 필요:** '+(qs.length?qs.length+'개 확인 질문을 검토해 주시기 바랍니다.':'없습니다.'));return lines.join('\n')}
function reportView(){const s=stats(state.record),valid=!!state.record.minutes.trim();return '<div class="panel"><div class="panel-header"><div class="panel-title">통합 회의 업무 결과</div><div class="actions"><button class="btn small" data-action="export-json">JSON 내보내기</button><button class="btn small" data-action="export-md">Markdown (.md)</button><button class="btn primary small" data-action="export-docx">워드 보고서 (.docx)</button><button class="btn small" data-action="template-docx">빈 워드 서식 (.docx)</button></div></div><div class="panel-body"><div class="section-note">첨부 양식의 7개 섹션을 기준으로 생성합니다. 원문에 없는 값은 확인필요로 두고, 완료·미완료 및 5대 기한 분류를 교차 검증합니다.</div>'+(!valid?'<div class="notice">회의록 원문이 비어 있어 업무 집계는 산출 불가입니다. 파일에서 내용을 확인한 뒤 원문 입력란에 입력해 주세요.</div>':'')+'<div class="grid3" style="margin:18px 0"><div class="stat"><div class="label">전체 업무</div><div class="number">'+(valid?s.all:'—')+'</div></div><div class="stat"><div class="label">완료</div><div class="number">'+(valid?s.done:'—')+'</div></div><div class="stat"><div class="label">검토 필요</div><div class="number accent">'+(valid?s.unknown+s.conflict+s.ownerMissing+s.statusMissing:'—')+'</div></div></div><div class="report"><pre>'+esc(markdown())+'</pre></div></div></div>'}
async function downloadWordFile(path,name){const response=await fetch(path);if(!response.ok){let detail;try{detail=await response.json()}catch{}throw Error(detail?.error||'워드 문서를 내려받지 못했습니다.')}const blob=await response.blob(),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name.replace(/[\\/:*?"<>|]/g,'_');document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2000)}
function exportJson(){const r=state.record;const obj={execution_metadata:{dataset_type:r.dataset,base_date:r.baseDate,meeting_title:r.title,meeting_date:r.meetingDate,input_files:state.files.map(f=>f.name),data_scope:r.scope,linked_previous_version:r.previousVersion,applied_version:r.version},meeting_minutes:{status:r.minutes.trim()?'포함':'없음',records:numbered(r.minutes,'M').map(x=>({source_id:x.id,raw_text:x.text}))},progress_records:{status:r.progress.trim()?'포함':'없음',record_base_date:r.baseDate,records:numbered(r.progress,'P').map(x=>({source_id:x.id,evidence_text:x.text}))},tasks:r.tasks,attendees:r.attendees,attachments:state.files.map(f=>({id:f.id,name:f.name,type:f.type,size:f.size,kind:f.kind}))};download(JSON.stringify(obj,null,2),'application/json',r.title+'-입력자료.json')}
function download(data,type,name){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([data],{type}));a.href=url;a.download=name.replace(/[\\/:*?"<>|]/g,'_');document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2000)}
function setupCanvas(){const c=$('#signature-canvas');if(!c)return;const rect=c.getBoundingClientRect(),ratio=devicePixelRatio||1;c.width=Math.max(1,Math.round(rect.width*ratio));c.height=Math.round(180*ratio);const ctx=c.getContext('2d');ctx.scale(ratio,ratio);ctx.strokeStyle='#20375a';ctx.lineWidth=2.5;ctx.lineCap='round';let drawing=false;const point=e=>{const r=c.getBoundingClientRect();return [e.clientX-r.left,e.clientY-r.top]};c.addEventListener('pointerdown',e=>{drawing=true;c.setPointerCapture(e.pointerId);const p=point(e);ctx.beginPath();ctx.moveTo(...p)});c.addEventListener('pointermove',e=>{if(!drawing)return;ctx.lineTo(...point(e));ctx.stroke()});c.addEventListener('pointerup',()=>drawing=false);c.addEventListener('pointercancel',()=>drawing=false)}
async function saveSignature(){const id=$('#signature-person')?.value,person=state.record.attendees.find(a=>a.id===id);if(!person){notify('서명자를 선택해 주세요.');return}const canvas=$('#signature-canvas');const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(!blob){notify('서명을 저장할 수 없습니다.');return}const file=new File([blob],(person.name||'참석자')+'-온라인서명.png',{type:'image/png'});try{await uploadFile(file,'signature');person.signed=true;state.dirty=true;await save()}catch(e){notify(e.message)}}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;try{
 if(a==='home'){if(state.dirty&&!confirm('저장하지 않은 변경사항이 있습니다. 이동할까요?'))return;state.record=null;state.dirty=false;render()}
 else if(a==='new'){state.modal=true;render();setTimeout(()=>$('#new-title')?.focus(),0)}
 else if(a==='close-modal'){state.modal=false;render()}
 else if(a==='create')await create();
 else if(a==='open')await openMeeting(b.dataset.id);
 else if(a==='save')await save();
 else if(a==='delete-meeting')await delMeeting();
 else if(a==='tab'){state.tab=b.dataset.tab;render();if(state.tab==='people')setupCanvas()}
 else if(a==='add-task'){state.record.tasks.push({id:'T'+String(state.record.tasks.length+1).padStart(2,'0'),text:'',assignee:'',due:'',rawDue:'',status:'상태 확인필요',completedDate:'',sourceRefs:'',progressEvidence:'',conflictValue:'',changeApproval:'해당없음'});state.dirty=true;render()}
 else if(a==='remove-task'){state.record.tasks.splice(Number(b.dataset.index),1);state.dirty=true;render()}
 else if(a==='add-person'){state.record.attendees.push({id:crypto.randomUUID(),name:'',role:'',present:true,signed:false});state.dirty=true;render();setupCanvas()}
 else if(a==='remove-person'){state.record.attendees.splice(Number(b.dataset.index),1);state.dirty=true;render();setupCanvas()}
 else if(a==='extract')extract();
 else if(a==='delete-file')await deleteFile(b.dataset.file);
 else if(a==='process-file')await processAttachment(b.dataset.file);
 else if(a==='start-transcription')await startTranscription();
 else if(a==='apply-import')await applyImport();
 else if(a==='dismiss-import')closeImport();
 else if(a==='export-md')download(markdown(),'text/markdown;charset=utf-8',state.record.title+'-회의결과.md');
 else if(a==='export-docx'){if(state.dirty)await save();if(!state.dirty)await downloadWordFile('/api/meetings/'+state.record.id+'/report.docx',state.record.title+'-회의결과.docx')}
 else if(a==='template-docx')await downloadWordFile('/api/report-template.docx','회의결과_보고서_서식.docx');
 else if(a==='export-json')exportJson();
 else if(a==='clear-signature'){const c=$('#signature-canvas');c?.getContext('2d').clearRect(0,0,c.width,c.height)}
 else if(a==='save-signature')await saveSignature();
 }catch(err){notify(err.message)}});
function updateField(el){if(!state.record)return;if(el.dataset.field){state.record[el.dataset.field]=el.value;state.dirty=true}else if(el.dataset.task!==undefined){state.record.tasks[Number(el.dataset.task)][el.dataset.key]=el.value;state.dirty=true}else if(el.dataset.person!==undefined){state.record.attendees[Number(el.dataset.person)][el.dataset.key]=el.type==='checkbox'?el.checked:el.value;state.dirty=true}if(state.dirty)renderHeader()}
document.addEventListener('input',e=>{if(e.target.id==='import-text'&&state.importDraft)state.importDraft.text=e.target.value;else if(e.target.matches('[data-field],[data-task],[data-person]'))updateField(e.target)});
document.addEventListener('change',e=>{if(e.target.id==='file-input')uploadSelected(e.target);else if(e.target.id==='import-target'&&state.importDraft)state.importDraft.target=e.target.value;else if(e.target.matches('[data-field],[data-task],[data-person]'))updateField(e.target)});
document.addEventListener('dragover',e=>{if(e.target.closest('.upload-zone'))e.preventDefault()});
document.addEventListener('drop',e=>{if(e.target.closest('.upload-zone')){e.preventDefault();const input=$('#file-input');if(input){input.files=e.dataTransfer.files;uploadSelected(input)}}});
window.addEventListener('beforeunload',e=>{if(state.dirty){e.preventDefault();e.returnValue=''}});
load();
