export default {async fetch(request,env,ctx){void ctx;const url=new URL(request.url);if(url.pathname.startsWith('/api/')){try{return await handleApi(request,env,url)}catch(e){return error('서버 오류: '+(e?.message||'알 수 없는 오류'),500)}}if(url.pathname==='/')return new Response(html,{headers:{'content-type':'text/html; charset=utf-8','cache-control':'no-store','x-content-type-options':'nosniff'}});if(url.pathname==='/app.css')return new Response(css,{headers:{'content-type':'text/css; charset=utf-8','cache-control':'no-store'}});if(url.pathname==='/jszip.min.js')return new Response(jszipCode,{headers:{'content-type':'application/javascript; charset=utf-8','cache-control':'no-store'}});if(url.pathname==='/app.js')return new Response(client,{headers:{'content-type':'application/javascript; charset=utf-8','cache-control':'no-store'}});return new Response('Not found',{status:404})}};
